-- ----------------------------
-- Table structure for admin
-- ----------------------------
DROP TABLE IF EXISTS `admin`;
CREATE TABLE `admin` (
  `id` varchar(255) COLLATE utf8mb4_bin NOT NULL,
  `real_name` varchar(255) COLLATE utf8mb4_bin NOT NULL DEFAULT '',
  `username` varchar(255) COLLATE utf8mb4_bin NOT NULL,
  `email` varchar(255) COLLATE utf8mb4_bin DEFAULT NULL,
  `phone` varchar(255) COLLATE utf8mb4_bin DEFAULT NULL,
  `avatar` varchar(255) COLLATE utf8mb4_bin DEFAULT NULL,
  `password` varchar(255) COLLATE utf8mb4_bin NOT NULL,
  `created_at` timestamp NOT NULL,
  `updated_at` timestamp NOT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `status` enum('enabled','disabled') COLLATE utf8mb4_bin NOT NULL DEFAULT 'enabled' COMMENT '状态：enabled=启用 disabled=禁用',
  `tenant_id` varchar(36) COLLATE utf8mb4_bin NOT NULL DEFAULT 'default' COMMENT '租户ID',
  `department_id` varchar(255) COLLATE utf8mb4_bin DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `admin_tenant_id` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='管理员表';

-- ----------------------------
-- Records of admin
-- ----------------------------
BEGIN;
COMMIT;

