  KEY `admindatapermission_tenant_id` (`tenant_id`),
  KEY `admin_data_permission_data_permission_data_permission` (`data_permission_id`),
  CONSTRAINT `admin_data_permission_admin_admin` FOREIGN KEY (`admin_id`) REFERENCES `admin` (`id`),
  CONSTRAINT `admin_data_permission_data_permission_data_permission` FOREIGN KEY (`data_permission_id`) REFERENCES `data_permission` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='管理员数据权限规则关联表';

