  `id` varchar(36) COLLATE utf8mb4_bin NOT NULL,
  `service` varchar(128) COLLATE utf8mb4_bin NOT NULL COMMENT '服务全限定名，如 admin.service.v1.PermissionService',
  `method` varchar(10) COLLATE utf8mb4_bin NOT NULL COMMENT 'HTTP method: GET/POST/PUT/DELETE',
  `path` varchar(256) COLLATE utf8mb4_bin NOT NULL COMMENT '接口路径，如 /admin/v1/menu',
  `summary` varchar(256) COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '接口描述',
  `code` varchar(512) COLLATE utf8mb4_bin NOT NULL COMMENT '业务唯一键 service|method|path',
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='接口权限表（菜单按钮绑定）';

-- ----------------------------
-- Records of api_permission
