-- ----------------------------
-- Table structure for data_permission
-- ----------------------------
DROP TABLE IF EXISTS `data_permission`;
CREATE TABLE `data_permission` (
  `id` varchar(36) COLLATE utf8mb4_bin NOT NULL COMMENT '规则ID',
  `name` varchar(64) COLLATE utf8mb4_bin NOT NULL COMMENT '规则名称',
  `code` varchar(100) COLLATE utf8mb4_bin NOT NULL COMMENT '规则编码',
  `scope_type` varchar(1) COLLATE utf8mb4_bin NOT NULL DEFAULT '1' COMMENT '数据范围（1=全部数据 2=自定义 3=本部门 4=本部门及以下 5=仅本人）',
  `dept_ids` varchar(2000) COLLATE utf8mb4_bin DEFAULT '[]' COMMENT '自定义数据范围的部门ID集合（JSON数组）',
  `role_ids` varchar(2000) COLLATE utf8mb4_bin DEFAULT '[]' COMMENT '自定义数据范围的角色ID集合（JSON数组）',
  `status` enum('enabled','disabled') COLLATE utf8mb4_bin NOT NULL DEFAULT 'enabled' COMMENT '状态',
  `remark` varchar(256) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `created_at` timestamp NOT NULL COMMENT '创建时间',
  `updated_at` timestamp NOT NULL COMMENT '更新时间',
  `deleted_at` timestamp NULL DEFAULT NULL COMMENT '删除时间',
  `tenant_id` varchar(36) COLLATE utf8mb4_bin NOT NULL DEFAULT 'default' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`),
  KEY `datapermission_tenant_id` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='数据权限规则表';

