-- ----------------------------
-- Table structure for form_schema
-- ----------------------------
DROP TABLE IF EXISTS `form_schema`;
CREATE TABLE `form_schema` (
  `id` varchar(36) COLLATE utf8mb4_bin NOT NULL COMMENT '表单ID',
  `tenant_id` varchar(36) COLLATE utf8mb4_bin NOT NULL DEFAULT 'default' COMMENT '租户ID',
  `name` varchar(64) COLLATE utf8mb4_bin NOT NULL COMMENT '表单名称',
  `code` varchar(64) COLLATE utf8mb4_bin NOT NULL COMMENT '表单编码（唯一，供运行时渲染引用）',
  `description` varchar(255) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '表单描述',
  `schema_json` json DEFAULT NULL COMMENT '表单 JSON Schema 定义',
  `status` enum('enabled','disabled') COLLATE utf8mb4_bin NOT NULL DEFAULT 'enabled' COMMENT '状态',
  `remark` varchar(256) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `created_at` timestamp NOT NULL COMMENT '创建时间',
  `updated_at` timestamp NOT NULL COMMENT '更新时间',
  `deleted_at` timestamp NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`),
  KEY `formschema_tenant_id` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='表单构建器-表单定义表';

