  `tenant_id` varchar(36) COLLATE utf8mb4_bin NOT NULL DEFAULT 'default' COMMENT '租户ID',
  `form_code` varchar(64) COLLATE utf8mb4_bin NOT NULL COMMENT '表单编码',
  `form_name` varchar(64) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '表单名称（冗余，便于列表展示）',
