  PRIMARY KEY (`id`),
  KEY `formsubmission_tenant_id` (`tenant_id`),
  KEY `formsubmission_form_code` (`form_code`),
  KEY `formsubmission_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='表单构建器-提交数据表';

