-- ----------------------------
-- Table structure for gen_table
-- ----------------------------
DROP TABLE IF EXISTS `gen_table`;
CREATE TABLE `gen_table` (
  `id` varchar(36) COLLATE utf8mb4_bin NOT NULL COMMENT '配置ID',
  `tenant_id` varchar(36) COLLATE utf8mb4_bin NOT NULL DEFAULT 'default' COMMENT '租户ID',
  `table_name` varchar(100) COLLATE utf8mb4_bin NOT NULL COMMENT '数据库表名',
  `table_comment` varchar(255) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '表备注',
  `module_name` varchar(50) COLLATE utf8mb4_bin NOT NULL COMMENT '模块名',
  `biz_name` varchar(100) COLLATE utf8mb4_bin NOT NULL COMMENT '业务名（驼峰）',
  `fields_json` json DEFAULT NULL COMMENT '字段配置',
  `gen_type` varchar(20) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '生成类型',
  `status` enum('enabled','disabled') COLLATE utf8mb4_bin NOT NULL DEFAULT 'enabled' COMMENT '状态',
  `created_at` timestamp NOT NULL COMMENT '创建时间',
  `updated_at` timestamp NOT NULL COMMENT '更新时间',
  `deleted_at` timestamp NULL DEFAULT NULL COMMENT '删除时间',
  `menu_enabled` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否生成菜单',
  `menu_module` varchar(50) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '菜单所属模块',
  `buttons_json` json DEFAULT NULL COMMENT '生成的按钮列表',
  PRIMARY KEY (`id`),
  KEY `gentable_tenant_id` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='代码生成器-生成表配置表';

