COMMIT;

-- ----------------------------
-- Table structure for login_log
-- ----------------------------
DROP TABLE IF EXISTS `login_log`;
CREATE TABLE `login_log` (
  `id` varchar(36) COLLATE utf8mb4_bin NOT NULL COMMENT '日志ID',
  `admin_id` varchar(36) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '用户ID（登录成功时记录）',
  `username` varchar(64) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '登录用户名（失败时也记录，便于排查撞库）',
  `ip` varchar(64) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '来源IP',
  `user_agent` varchar(512) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '客户端 UA',
  `status` enum('success','fail') COLLATE utf8mb4_bin NOT NULL DEFAULT 'success' COMMENT '结果：success=成功 fail=失败',
  `reason` varchar(128) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '失败原因（错误码或简要说明）',
  `created_at` timestamp NOT NULL COMMENT '登录时间',
  `tenant_id` varchar(36) COLLATE utf8mb4_bin NOT NULL DEFAULT 'default' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  KEY `loginlog_username_created_at` (`username`,`created_at`),
  KEY `loginlog_status_created_at` (`status`,`created_at`),
  KEY `loginlog_created_at` (`created_at`),
  KEY `loginlog_tenant_id` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='登录日志表';

-- ----------------------------
-- Records of login_log
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for menu
-- ----------------------------
DROP TABLE IF EXISTS `menu`;
CREATE TABLE `menu` (
  `id` varchar(36) COLLATE utf8mb4_bin NOT NULL,
  `parent_id` varchar(255) COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '父菜单ID, null表示根节点',
  `name` varchar(64) COLLATE utf8mb4_bin NOT NULL COMMENT '菜单名称',
  `remark` varchar(256) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `path` varchar(256) COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '路由路径',
  `icon` varchar(128) COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '图标',
  `type` enum('menu_dir','catalog','menu','iframe','link','action','button') COLLATE utf8mb4_bin NOT NULL DEFAULT 'menu_dir' COMMENT '类型:catalog=菜单目录,menu=菜单项,iframe=内嵌,link=外链,action=页面按钮',
  `menu_type` enum('tab','link','iframe') COLLATE utf8mb4_bin NOT NULL DEFAULT 'tab' COMMENT '菜单类型:tab=选项卡,link=链接(站外),iframe=Iframe',
  `component` varchar(256) COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '组件路径',
  `weight` bigint NOT NULL DEFAULT '0' COMMENT '权重',
  `status` enum('enabled','disabled') COLLATE utf8mb4_bin NOT NULL DEFAULT 'enabled' COMMENT '状态：enabled=启用 disabled=禁用',
  `created_at` timestamp NOT NULL,
  `updated_at` timestamp NOT NULL,
  `title` varchar(60) COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '标题（国际化 key）',
  `auth_code` varchar(100) COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '权限标识',
  `badge_type` varchar(20) COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '徽标类型:dot=圆点,text=文本',
  `code` varchar(64) COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '菜单唯一编码',
  `url` varchar(256) COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '链接地址（iframe/外链）',
  `badge` varchar(10) COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '徽标内容',
  `badge_variants` varchar(20) COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '徽标样式:default/destructive/primary/success/warning',
  `tenant_id` varchar(36) COLLATE utf8mb4_bin NOT NULL DEFAULT 'default' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  KEY `menu_tenant_id` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='菜单表';

-- ----------------------------
-- Records of menu
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for menu_api_permission
-- ----------------------------
DROP TABLE IF EXISTS `menu_api_permission`;
CREATE TABLE `menu_api_permission` (
  `id` varchar(36) COLLATE utf8mb4_bin NOT NULL,
  `tenant_id` varchar(36) COLLATE utf8mb4_bin NOT NULL DEFAULT 'default' COMMENT '租户ID',
  `menu_id` varchar(36) COLLATE utf8mb4_bin NOT NULL COMMENT '菜单ID',
  `api_code` varchar(512) COLLATE utf8mb4_bin NOT NULL COMMENT '接口业务唯一键 service|METHOD|path（对应 api_interface.code）',
  `created_at` timestamp NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `menuapipermission_menu_id_api_code` (`menu_id`,`api_code`),
  KEY `menuapipermission_tenant_id` (`tenant_id`),
  KEY `menuapipermission_api_code` (`api_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='菜单接口绑定表（菜单按钮 ↔ 接口 code）';

-- ----------------------------
-- Records of menu_api_permission
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for notification
-- ----------------------------
DROP TABLE IF EXISTS `notification`;
CREATE TABLE `notification` (
  `id` varchar(36) COLLATE utf8mb4_bin NOT NULL COMMENT '通知ID',
  `title` varchar(128) COLLATE utf8mb4_bin NOT NULL COMMENT '通知标题',
  `content` varchar(1024) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '通知内容',
  `type` enum('system','announce','audit','todo','alert') COLLATE utf8mb4_bin NOT NULL DEFAULT 'system' COMMENT '通知类型：system=系统 announce=公告 audit=审批 todo=待办 alert=告警',
  `level` enum('info','success','warn','error') COLLATE utf8mb4_bin NOT NULL DEFAULT 'info' COMMENT '重要级别：info=普通 success=成功 warn=警告 error=严重',
  `biz_type` varchar(64) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务类型，用于业务方归类（如 order、admin）',
  `biz_id` varchar(64) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '业务ID，配合 biz_type 定位数据来源',
  `sender_id` varchar(36) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '发送人ID，空表示系统发送',
  `sender_name` varchar(64) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '发送人名称（冗余，避免联表）',
  `link` varchar(256) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '点击后跳转的前端路由',
  `target_type` enum('all','user','role') COLLATE utf8mb4_bin NOT NULL DEFAULT 'all' COMMENT '投放范围：all=全体用户 user=指定用户 role=指定角色',
  `target_ids` json DEFAULT NULL COMMENT '投放目标ID集合，target_type 为 all 时为空',
  `status` enum('draft','published','revoked') COLLATE utf8mb4_bin NOT NULL DEFAULT 'published' COMMENT '状态：draft=草稿 published=已发布 revoked=已撤回',
  `published_at` timestamp NULL DEFAULT NULL COMMENT '发布时间',
  `expire_at` timestamp NULL DEFAULT NULL COMMENT '过期时间，为空表示长期有效',
  `created_at` timestamp NOT NULL COMMENT '创建时间',
  `updated_at` timestamp NOT NULL COMMENT '更新时间',
  `deleted_at` timestamp NULL DEFAULT NULL COMMENT '删除时间',
  `tenant_id` varchar(36) COLLATE utf8mb4_bin NOT NULL DEFAULT 'default' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  KEY `notification_status_created_at` (`status`,`created_at`),
  KEY `notification_biz_type_biz_id` (`biz_type`,`biz_id`),
  KEY `notification_tenant_id` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='通知表';

-- ----------------------------
-- Records of notification
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for notification_record
-- ----------------------------
DROP TABLE IF EXISTS `notification_record`;
CREATE TABLE `notification_record` (
  `id` varchar(36) COLLATE utf8mb4_bin NOT NULL COMMENT '记录ID',
  `user_id` varchar(36) COLLATE utf8mb4_bin NOT NULL COMMENT '接收人ID',
  `is_read` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已读',
  `read_at` timestamp NULL DEFAULT NULL COMMENT '已读时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已删除（回收站，用户侧软删）',
  `created_at` timestamp NOT NULL COMMENT '创建时间',
  `updated_at` timestamp NOT NULL COMMENT '更新时间',
  `notification_id` varchar(36) COLLATE utf8mb4_bin NOT NULL COMMENT '通知ID',
  `tenant_id` varchar(36) COLLATE utf8mb4_bin NOT NULL DEFAULT 'default' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `notificationrecord_notification_id_user_id` (`notification_id`,`user_id`),
  KEY `notificationrecord_user_id_is_read_is_deleted` (`user_id`,`is_read`,`is_deleted`),
  KEY `notificationrecord_tenant_id` (`tenant_id`),
  CONSTRAINT `notification_record_notification_records` FOREIGN KEY (`notification_id`) REFERENCES `notification` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='用户通知收件表';

-- ----------------------------
-- Records of notification_record
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for operation_log
-- ----------------------------
DROP TABLE IF EXISTS `operation_log`;
CREATE TABLE `operation_log` (
  `id` varchar(36) COLLATE utf8mb4_bin NOT NULL COMMENT '日志ID',
  `admin_id` varchar(36) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '操作人ID（未登录操作为空）',
  `admin_name` varchar(64) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '操作人姓名（冗余，避免联表）',
  `module` varchar(64) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '所属模块/服务名，如 Admin、Dictionary',
  `operation` varchar(128) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '操作名，如 CreateAdmin',
  `method` varchar(16) COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'HTTP 方法',
  `path` varchar(256) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '请求路径',
  `summary` varchar(256) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '接口中文摘要（来自 OpenAPI）',
  `ip` varchar(64) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '来源IP',
  `user_agent` varchar(512) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '客户端 UA',
  `params` longtext COLLATE utf8mb4_bin COMMENT '请求参数（JSON，已脱敏并截断）',
  `status` enum('success','fail') COLLATE utf8mb4_bin NOT NULL DEFAULT 'success' COMMENT '结果：success=成功 fail=失败',
  `code` varchar(64) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '失败时的错误码',
  `message` varchar(512) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '失败时的错误信息',
  `cost_ms` bigint NOT NULL DEFAULT '0' COMMENT '耗时（毫秒）',
  `created_at` timestamp NOT NULL COMMENT '操作时间',
  `tenant_id` varchar(36) COLLATE utf8mb4_bin NOT NULL DEFAULT 'default' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  KEY `operationlog_admin_id_created_at` (`admin_id`,`created_at`),
  KEY `operationlog_status_created_at` (`status`,`created_at`),
  KEY `operationlog_created_at` (`created_at`),
  KEY `operationlog_tenant_id` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='操作日志表';

-- ----------------------------
-- Records of operation_log
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for order
-- ----------------------------
DROP TABLE IF EXISTS `order`;
CREATE TABLE `order` (
  `id` varchar(36) COLLATE utf8mb4_bin NOT NULL COMMENT 'ID',
  `name` varchar(255) COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'name',
