-- ----------------------------
-- Table structure for organization
-- ----------------------------
DROP TABLE IF EXISTS `organization`;
CREATE TABLE `organization` (
  `id` varchar(36) COLLATE utf8mb4_bin NOT NULL,
  `parent_id` varchar(255) COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '父部门ID，空表示根节点',
  `name` varchar(64) COLLATE utf8mb4_bin NOT NULL COMMENT '部门名称',
  `code` varchar(64) COLLATE utf8mb4_bin NOT NULL COMMENT '部门code',
  `weight` bigint NOT NULL DEFAULT '0' COMMENT '权重',
  `status` enum('enabled','disabled') COLLATE utf8mb4_bin NOT NULL DEFAULT 'enabled' COMMENT '状态：enabled=启用 disabled=禁用',
  `leader_name` varchar(64) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '负责人姓名',
  `leader_phone` varchar(20) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '联系电话',
  `leader_email` varchar(128) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '邮箱',
  `created_at` timestamp NOT NULL,
  `updated_at` timestamp NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='权限表';

