-- ----------------------------
-- Table structure for permission
-- ----------------------------
DROP TABLE IF EXISTS `permission`;
CREATE TABLE `permission` (
  `id` varchar(36) COLLATE utf8mb4_bin NOT NULL,
  `parent_id` varchar(255) COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '父权限ID, null表示根节点',
  `name` varchar(64) COLLATE utf8mb4_bin NOT NULL COMMENT '权限名称',
  `code` varchar(64) COLLATE utf8mb4_bin NOT NULL COMMENT '权限唯一编码',
  `description` varchar(256) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '权限描述',
  `path` varchar(256) COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '路由路径',
  `icon` varchar(128) COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '图标',
  `type` enum('menu_dir','menu','button') COLLATE utf8mb4_bin NOT NULL DEFAULT 'menu_dir' COMMENT '类型:menu_dir=菜单目录,menu=菜单项,button=页面按钮',
  `menu_type` enum('tab','link','iframe') COLLATE utf8mb4_bin NOT NULL DEFAULT 'tab' COMMENT '菜单类型:tab=选项卡,link=链接(站外),iframe=Iframe',
  `url` varchar(256) COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT 'URL',
  `component` varchar(256) COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '组件路径',
  `weight` bigint NOT NULL DEFAULT '0' COMMENT '权重',
  `status` enum('enabled','disabled') COLLATE utf8mb4_bin NOT NULL DEFAULT 'enabled' COMMENT '状态：enabled=启用 disabled=禁用=禁用',
  `created_at` timestamp NOT NULL,
  `updated_at` timestamp NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='权限表';

-- ----------------------------
-- Records of permission
-- ----------------------------
BEGIN;
COMMIT;

