  `updated_by` varchar(255) COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '更新人',
  `deleted_by` varchar(255) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '删除人',
  `tenant_id` varchar(36) COLLATE utf8mb4_bin NOT NULL DEFAULT 'default' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `position_code_deleted_at` (`code`,`deleted_at`),
  KEY `position_tenant_id` (`tenant_id`)
