-- ----------------------------
-- Table structure for security_policy
-- ----------------------------
DROP TABLE IF EXISTS `security_policy`;
CREATE TABLE `security_policy` (
  `id` varchar(36) COLLATE utf8mb4_bin NOT NULL COMMENT '策略ID（固定为 default）',
  `login_fail_enabled` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否启用登录失败次数限制',
  `login_fail_max` bigint NOT NULL DEFAULT '5' COMMENT '窗口内允许的最大失败次数',
  `login_fail_window_minutes` bigint NOT NULL DEFAULT '15' COMMENT '失败次数统计窗口（分钟）',
  `login_lock_minutes` bigint NOT NULL DEFAULT '15' COMMENT '达到上限后的锁定时长（分钟）',
  `ip_mode` enum('off','whitelist','blacklist') COLLATE utf8mb4_bin NOT NULL DEFAULT 'off' COMMENT 'IP 访问控制模式：off=关闭 whitelist=白名单 blacklist=黑名单',
  `ip_list` longtext COLLATE utf8mb4_bin COMMENT 'IP 列表（换行或逗号分隔，支持 CIDR）',
  `access_token_ttl_seconds` bigint NOT NULL DEFAULT '7200' COMMENT 'access token 有效期（秒），合法范围 60-2592000，0 回退默认值 7200',
  `refresh_token_ttl_seconds` bigint NOT NULL DEFAULT '604800' COMMENT 'refresh token 有效期（秒），合法范围 300-31536000，0 回退默认值 604800',
  `remark` varchar(256) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `created_at` timestamp NOT NULL COMMENT '创建时间',
  `updated_at` timestamp NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='安全策略配置表（单例）';

-- ----------------------------
-- Records of security_policy
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_config
-- ----------------------------
DROP TABLE IF EXISTS `sys_config`;
CREATE TABLE `sys_config` (
  `id` varchar(36) COLLATE utf8mb4_bin NOT NULL COMMENT '参数ID',
  `name` varchar(64) COLLATE utf8mb4_bin NOT NULL COMMENT '参数名称',
  `key` varchar(100) COLLATE utf8mb4_bin NOT NULL COMMENT '参数键名',
  `value` varchar(512) COLLATE utf8mb4_bin NOT NULL COMMENT '参数键值',
  `config_type` enum('Y','N') COLLATE utf8mb4_bin NOT NULL DEFAULT 'N' COMMENT '系统内置（Y=内置，N=外置）',
  `status` enum('enabled','disabled') COLLATE utf8mb4_bin NOT NULL DEFAULT 'enabled' COMMENT '状态',
  `remark` varchar(256) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `created_at` timestamp NOT NULL COMMENT '创建时间',
  `updated_at` timestamp NOT NULL COMMENT '更新时间',
  `deleted_at` timestamp NULL DEFAULT NULL COMMENT '删除时间',
  `tenant_id` varchar(36) COLLATE utf8mb4_bin NOT NULL DEFAULT 'default' COMMENT '租户ID',
  `group` varchar(50) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '分组名称（可为空，即单一参数）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `key` (`key`),
  KEY `sysconfig_tenant_id` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='系统参数配置表';

-- ----------------------------
-- Records of sys_config
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_job
-- ----------------------------
DROP TABLE IF EXISTS `sys_job`;
CREATE TABLE `sys_job` (
  `id` varchar(36) COLLATE utf8mb4_bin NOT NULL COMMENT '任务ID',
  `name` varchar(64) COLLATE utf8mb4_bin NOT NULL COMMENT '任务名称',
  `job_group` varchar(64) COLLATE utf8mb4_bin NOT NULL DEFAULT 'DEFAULT' COMMENT '任务分组',
  `job_type` varchar(32) COLLATE utf8mb4_bin NOT NULL DEFAULT 'http' COMMENT '任务类型（http=HTTP调用）',
  `invoke_target` varchar(512) COLLATE utf8mb4_bin NOT NULL COMMENT '调用目标（HTTP请求URL）',
  `cron_expression` varchar(64) COLLATE utf8mb4_bin NOT NULL COMMENT 'Cron 表达式',
  `misfire_policy` varchar(32) COLLATE utf8mb4_bin NOT NULL DEFAULT 'immediately' COMMENT '错失执行策略（immediately=立即执行，once=执行一次，ignore=放弃执行）',
  `concurrent` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否允许并发执行',
  `status` enum('enabled','disabled') COLLATE utf8mb4_bin NOT NULL DEFAULT 'enabled' COMMENT '状态',
  `remark` varchar(256) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `next_run_time` timestamp NULL DEFAULT NULL COMMENT '下次执行时间',
  `created_at` timestamp NOT NULL COMMENT '创建时间',
  `updated_at` timestamp NOT NULL COMMENT '更新时间',
  `deleted_at` timestamp NULL DEFAULT NULL COMMENT '删除时间',
  `tenant_id` varchar(36) COLLATE utf8mb4_bin NOT NULL DEFAULT 'default' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  KEY `sysjob_tenant_id` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='定时任务表';

-- ----------------------------
-- Records of sys_job
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_job_log
-- ----------------------------
DROP TABLE IF EXISTS `sys_job_log`;
CREATE TABLE `sys_job_log` (
  `id` varchar(36) COLLATE utf8mb4_bin NOT NULL COMMENT '日志ID',
  `job_id` varchar(36) COLLATE utf8mb4_bin NOT NULL COMMENT '任务ID',
  `job_name` varchar(64) COLLATE utf8mb4_bin DEFAULT '' COMMENT '任务名称',
  `job_group` varchar(64) COLLATE utf8mb4_bin DEFAULT '' COMMENT '任务分组',
  `invoke_target` varchar(512) COLLATE utf8mb4_bin DEFAULT '' COMMENT '调用目标',
  `cron_expression` varchar(64) COLLATE utf8mb4_bin DEFAULT '' COMMENT 'Cron 表达式',
  `status` enum('success','fail') COLLATE utf8mb4_bin NOT NULL DEFAULT 'success' COMMENT '执行结果',
  `job_message` varchar(2000) COLLATE utf8mb4_bin DEFAULT '' COMMENT '执行信息',
  `start_time` timestamp NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` timestamp NULL DEFAULT NULL COMMENT '结束时间',
  `duration` bigint NOT NULL DEFAULT '0' COMMENT '耗时（毫秒）',
  `created_at` timestamp NOT NULL COMMENT '创建时间',
  `deleted_at` timestamp NULL DEFAULT NULL COMMENT '删除时间',
  `tenant_id` varchar(36) COLLATE utf8mb4_bin NOT NULL DEFAULT 'default' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  KEY `sysjoblog_tenant_id` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='定时任务执行日志表';

-- ----------------------------
-- Records of sys_job_log
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for tenant
-- ----------------------------
DROP TABLE IF EXISTS `tenant`;
CREATE TABLE `tenant` (
  `id` varchar(36) COLLATE utf8mb4_bin NOT NULL COMMENT '租户ID（默认租户固定为 default）',
  `code` varchar(64) COLLATE utf8mb4_bin NOT NULL COMMENT '租户编码（登录用，创建后不可修改）',
  `name` varchar(64) COLLATE utf8mb4_bin NOT NULL COMMENT '租户名称',
  `status` enum('enabled','disabled') COLLATE utf8mb4_bin NOT NULL DEFAULT 'enabled' COMMENT '状态：enabled=启用 disabled=禁用',
  `expire_at` timestamp NULL DEFAULT NULL COMMENT '到期时间，空表示永久',
  `max_users` bigint NOT NULL DEFAULT '0' COMMENT '用户数上限，0 表示不限',
  `max_roles` bigint NOT NULL DEFAULT '0' COMMENT '角色数上限，0 表示不限',
  `contact_name` varchar(64) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '联系人',
  `contact_phone` varchar(20) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '联系电话',
  `remark` varchar(256) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `created_at` timestamp NOT NULL COMMENT '创建时间',
  `updated_at` timestamp NOT NULL COMMENT '更新时间',
  `deleted_at` timestamp NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='租户表';

-- ----------------------------
-- Records of tenant
-- ----------------------------
BEGIN;
COMMIT;

